from collections import deque

class Solution:
    def networkBecomesIdle(self, edges: list[list[int]], patience: list[int]) -> int:
        n = len(patience)
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            curr = q.popleft()
            for nxt in adj[curr]:
                if dist[nxt] == -1:
                    dist[nxt] = dist[curr] + 1
                    q.append(nxt)

        max_time = 0
        for i in range(1, n):
            round_trip = 2 * dist[i]
            p = patience[i]
            last_sent = ((round_trip - 1) // p) * p
            last_received = last_sent + round_trip
            if last_received > max_time:
                max_time = last_received
        return max_time + 1

#include <vector>
#include <queue>
#include <algorithm>

class Solution {
public:
    int networkBecomesIdle(std::vector<std::vector<int>>& edges, std::vector<int>& patience) {
        int n = patience.size();
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::vector<int> dist(n, -1);
        dist[0] = 0;
        std::queue<int> q;
        q.push(0);

        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            for (int nxt : adj[curr]) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.push(nxt);
                }
            }
        }

        int maxTime = 0;
        for (int i = 1; i < n; ++i) {
            int roundTrip = 2 * dist[i];
            int p = patience[i];
            int lastSent = ((roundTrip - 1) / p) * p;
            int lastReceived = lastSent + roundTrip;
            maxTime = std::max(maxTime, lastReceived);
        }
        return maxTime + 1;
    }
};

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;

class Solution {
    public int networkBecomesIdle(int[][] edges, int[] patience) {
        int n = patience.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(0);

        while (!q.isEmpty()) {
            int curr = q.poll();
            for (int nxt : adj.get(curr)) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.offer(nxt);
                }
            }
        }

        int maxTime = 0;
        for (int i = 1; i < n; i++) {
            int roundTrip = 2 * dist[i];
            int p = patience[i];
            int lastSent = ((roundTrip - 1) / p) * p;
            int lastReceived = lastSent + roundTrip;
            if (lastReceived > maxTime) {
                maxTime = lastReceived;
            }
        }
        return maxTime + 1;
    }
}

