var networkBecomesIdle = function(edges, patience) {
    const n = patience.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const dist = new Array(n).fill(-1);
    dist[0] = 0;
    const q = [0];
    let head = 0;
    while (head < q.length) {
        const curr = q[head++];
        for (const nxt of adj[curr]) {
            if (dist[nxt] === -1) {
                dist[nxt] = dist[curr] + 1;
                q.push(nxt);
            }
        }
    }

    let maxTime = 0;
    for (let i = 1; i < n; i++) {
        const roundTrip = 2 * dist[i];
        const p = patience[i];
        const lastSent = Math.floor((roundTrip - 1) / p) * p;
        const lastReceived = lastSent + roundTrip;
        if (lastReceived > maxTime) {
            maxTime = lastReceived;
        }
    }
    return maxTime + 1;
};
